}

.request-insights-route-label {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.request-insights-row[data-internal='true'] .request-insights-route-label {
  color: var(--color-gray-900);
